r"""规范建议 4 的执行器：作者/单位字段的「出处门禁」。

背景（根因四）
--------------
QC 实测规律：**当支撑某条头衔断言的 raw 不含作者信息栏时，该断言几乎必然无出处。**
对照组（raw 含完整作者/单位/通讯栏的页面）⇒ 头衔、位次、基金号全部可核、零失真。

CLAUDE.md 的新规定：
  · raw 的作者信息栏未落库时，**强制留白并标 `⚠️ 信息缺口`，不得补写**；
  · AI 分析报告类来源页，作者/通讯字段**一律须走 Crossref / OpenAlex 反查**。

本工具做两件事
--------------
  1. **门禁扫描**：找出「`authors` 非空，但在其 raw 回链中检索不到作者/单位信息」
     的 source 页 → 这些页的作者字段**无出处**，须回源核验或留白。
  2. **三重校验**（建议 5 的第三条纪律）：
     `yaml.safe_load` 通过 **＋** 值为 list **＋** 每项不含引号与反斜杠。
     存在「能过但值脏」的 YAML（表面通过、下游匹配全落空）。

用法
----
  python tools/qc_author_gate.py              # 扫描报告
  python tools/qc_author_gate.py --json       # 机器可读
  python tools/qc_author_gate.py --selftest   # 夹具反算
"""
import sys
import os
import re
import glob
import json

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, split_frontmatter, parse_frontmatter  # noqa: E402
from kb_lib import console_encoding
console_encoding()

# raw 中出现这些词 ⇒ 该 raw 含作者/单位信息栏
AFF_PAT = re.compile(
    r"[Aa]ffiliation|[Cc]orresponding\s+author|[Ee]-?mail|@[a-z0-9.-]+\.|"
    r"[Uu]niversity|[Ii]nstitute|[Ll]aboratory|[Aa]cademy|"
    r"大学|研究所|学院|通讯作者|作者单位|实验室")

# 作者字段里的脏值指纹（建议 5 纪律三）
#
# ⚠️ 只查**结构破坏性**字符，**不要**把撇号当脏值（2026-09-25 实测假阳性）：
#   首版用 `[\"'\\]` 会把 5 个真实姓名判为脏值——
#   `S. W. D'Souza`、`Ouassim L'Karkouri`、`D'Avino`、`Gryn'ova`、`Xian'an Jin`
#   这些都是**正当的撇号**（O'/L'/D'/Gryn'/'an），不是 YAML 结构问题。
#   真正的脏值是：**转义反斜杠**、**成对的双引号**（会被 YAML 当字符串界符）、
#   **换行**。
DIRTY_PAT = re.compile(r"\\|\"|\n|\r")


def _has_structural_dirty(s):
    """判断单个作者项是否含**结构破坏性**字符。

    排除正当撇号：`'` 只要**不与其他引号配对**就不构成问题。
    这里只拒：反斜杠、双引号、换行。（单引号在 YAML 里若整体加引号会出问题，
    但本库 authors 写成裸 list，列表项里的 `'` 是安全的。）
    """
    if "\\" in s or '"' in s or "\n" in s or "\r" in s:
        return True
    return False


def raw_links(fm_raw):
    """取 frontmatter 里的 raw 回链路径。

    ⚠️ 不要用 `raw/[^\\]\\|\\)\\s]+` ——**本库 raw 路径含空格**
    （`raw/AI for Materials literatures Base/literatures-md/...`），
    `\\s` 排除空格会让所有这类链接**一条都取不到**，于是全部页面被误判
    「raw 0 条已查」（2026-09-25 实测：274 页误报）。
    正确做法：先按 wikilink 边界截取，**允许空格**，再取到 `]]`/`|` 为止。
    """
    out = []
    for m in re.findall(r"\[\[(raw/[^\]]+?)(?:\|[^\]]*)?\]\]", fm_raw):
        out.append(m.replace("\\", "/").strip())
    # 兼容裸路径写法（非 wikilink，历史遗留）
    for m in re.findall(r"(?<!\[\[)(raw/[^\s\]\|]+)", fm_raw):
        if not any(m in o for o in out):
            out.append(m.replace("\\", "/"))
    return out


def has_affiliation(fm_raw, max_check=4):
    """该页的 raw 回链中是否检索得到作者/单位信息。

    返回 (found: bool, checked: list[str])
    ⚠️ 只查前 max_check 条：本库 raw 回链常有多条（PDF 提取件 + HTML 剪藏），
       全查会慢；前几条已足够代表。
    """
    checked = []
    for r in raw_links(fm_raw)[:max_check]:
        if not os.path.exists(r):
            continue
        if r.lower().endswith(".pdf"):
            continue          # 二进制 PDF 不读
        checked.append(r)
        try:
            if AFF_PAT.search(read_text(r)):
                return True, checked
        except Exception:
            continue
    return False, checked


def three_way_check(authors):
    """建议 5 纪律三：authors 三重校验。返回问题列表（空 = 通过）。"""
    probs = []
    if authors is None:
        return ["缺失"]
    if isinstance(authors, str):
        # 单字符串也可能是本库允许的写法（如 "et al."），但若是长串则可疑
        if len(authors) > 120:
            probs.append(f"值为 str 且过长（{len(authors)} 字符）")
        return probs
    if not isinstance(authors, list):
        probs.append(f"类型异常: {type(authors).__name__}")
        return probs
    for i, a in enumerate(authors):
        s = str(a)
        if _has_structural_dirty(s):
            probs.append(f"第 {i+1} 项含结构破坏字符（反斜杠/双引号/换行）: {s[:50]!r}")
    return probs


def scan():
    rows = []
    for f in sorted(glob.glob("wiki/sources/*.md")):
        t = read_text(f)
        fm_raw, body = split_frontmatter(t)
        fm = parse_frontmatter(fm_raw)
        au = fm.get("authors")
        checked = []
        if au:
            found, checked = has_affiliation(fm_raw)
            if not found:
                # 已按建议 4 标注过 `authors_source` 的页，不再重复报
                # （标注本身就是对该问题的处置结论，重复报等于噪声）
                if fm.get("authors_source"):
                    rows.append({
                        "page": os.path.basename(f)[:-3],
                        "kind": "已标注不可回溯",
                        "detail": "authors_source 已声明库内不可回溯（已处置）",
                    })
                else:
                    rows.append({
                        "page": os.path.basename(f)[:-3],
                        "kind": "作者字段无出处",
                        "detail": f"authors 非空，但 raw（{len(checked)} 条已查）"
                                  f"中检索不到作者/单位信息",
                    })
        probs = three_way_check(au)
        # 只在有值时报「脏值」；缺失另计
        if probs and au:
            rows.append({
                "page": os.path.basename(f)[:-3],
                "kind": "authors 三重校验",
                "detail": "; ".join(probs),
            })
    return rows


def run_selftest():
    """夹具反算：正例反例都要有。"""
    cases = [
        # (描述, authors, 期望有问题的布尔值)
        ("正常 list", ["张三", "李四"], False),
        ("含双引号", ['张"三'], True),
        ("含反斜杠", ["张\\三"], True),
        ("空 list", [], False),
        ("None", None, True),          # None 由调用处过滤，但函数本身报缺失
        ("单作者", ["张三"], False),
        ("长字符串", "x" * 200, True),
        ("短字符串", "et al.", False),
        # —— 回归夹具：正当撇号不得被判脏（首版曾误报 5 个真实姓名）——
        ("D'Souza", ["S. W. D'Souza"], False),
        ("L'Karkouri", ["Ouassim L'Karkouri"], False),
        ("D'Avino", ["D'Avino"], False),
        ("Gryn'ova", ["Ganna Gryn'ova"], False),
        ("Xian'an Jin", ["Xian'an Jin"], False),
        # 反例：真脏值仍须报
        ("含换行", ["张三\n李四"], True),
    ]
    print("=== qc_author_gate selftest ===")
    failed = 0
    for desc, au, expect_bad in cases:
        probs = three_way_check(au)
        got_bad = bool(probs)
        ok = got_bad == expect_bad
        if not ok:
            failed += 1
        print(f"  [{'PASS' if ok else 'FAIL'}] {desc:<12} "
              f"expect_bad={expect_bad!s:<6} got={got_bad!s:<6} {probs}")
    print()
    if failed:
        print(f"SELFTEST FAILED: {failed}/{len(cases)} wrong")
        return 1
    print(f"SELFTEST PASSED: {len(cases)}/{len(cases)} correct")
    return 0


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/qc_author_gate.py [--json] [--selftest]")
        return 0
    if "--selftest" in sys.argv:
        return run_selftest()
    rows = scan()
    if "--json" in sys.argv:
        print(json.dumps(rows, ensure_ascii=False, indent=1))
        return 0

    by_kind = {}
    for r in rows:
        by_kind.setdefault(r["kind"], []).append(r)

    print("=== 作者字段门禁扫描 ===\n")
    for kind in ("作者字段无出处", "已标注不可回溯", "authors 三重校验"):
        items = by_kind.get(kind, [])
        print(f"🔴 {kind}: {len(items)} 页")
        for r in items[:20]:
            print(f"   {r['page'][:52]:<54} {r['detail']}")
        if len(items) > 20:
            print(f"   ... 另 {len(items) - 20} 页")
        print()

    print("处置规则（CLAUDE.md §Ingest 增强）：")
    print("  · 「作者字段无出处」→ **回 raw 原文核验**；核不到则**强制留白**")
    print("    并在 source 页标 `> ⚠️ 信息缺口：raw 无作者信息栏，作者/单位未核`")
    print("  · AI 分析报告类来源页 → 作者/通讯字段**一律走 Crossref / OpenAlex 反查**")
    print("  · 「三重校验」问题项 → 就地修正值（去引号/反斜杠）")
    return 0


if __name__ == "__main__":
    sys.exit(main())
